-- Phase 2: tenancy, RLS and data foundations.
--
-- Sections:
--   1. Extensions, schema privileges and the `app` schema
--   2. Enums (generated by Prisma)
--   3. Context helper functions (app.*)
--   4. Tables, indexes, foreign keys (generated by Prisma)
--   5. Hand-written constraints Prisma cannot model
--   6. Audit log immutability
--   7. Grants
--   8. Row-level security
--
-- Runs as ogs_owner. Runtime role ogs_app never owns anything and has NOBYPASSRLS.

-- ===========================================================================
-- 1. Extensions, schema privileges and the `app` schema
-- ===========================================================================

-- citext is a trusted extension: the database owner may create it.
CREATE EXTENSION IF NOT EXISTS citext WITH SCHEMA public;

-- Re-applied here (also done by the roles script) so a `prisma migrate reset`,
-- which recreates schema public, leaves the same privileges behind.
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
GRANT USAGE ON SCHEMA public TO ogs_app, ogs_readonly, ogs_maint;

CREATE SCHEMA IF NOT EXISTS app;
REVOKE ALL ON SCHEMA app FROM PUBLIC;
GRANT USAGE ON SCHEMA app TO ogs_app, ogs_readonly, ogs_maint;

-- ===========================================================================
-- 2. Enums
-- ===========================================================================

-- CreateEnum
CREATE TYPE "TenantKind" AS ENUM ('ORGANISATION', 'PROVIDER_COMPANY', 'PLATFORM');

-- CreateEnum
CREATE TYPE "TenantStatus" AS ENUM ('PENDING_APPROVAL', 'ACTIVE', 'REJECTED', 'SUSPENDED', 'CLOSED');

-- CreateEnum
CREATE TYPE "UserStatus" AS ENUM ('PENDING_VERIFICATION', 'ACTIVE', 'SUSPENDED', 'DEACTIVATED');

-- CreateEnum
CREATE TYPE "MembershipStatus" AS ENUM ('INVITED', 'ACTIVE', 'SUSPENDED', 'ENDED');

-- CreateEnum
CREATE TYPE "ActorKind" AS ENUM ('USER', 'SYSTEM');

-- ===========================================================================
-- 3. Context helper functions
-- ===========================================================================
-- The API sets these GUCs ONLY with set_config(name, value, true) inside a
-- transaction (TenantDb), so they vanish at COMMIT/ROLLBACK and can never leak
-- to the next user of a pooled connection.
--
-- Once a custom GUC has been set on a session it reverts to '' (not NULL) after
-- the transaction. nullif(..., '') turns both "never set" and "reverted" into
-- NULL, so policies fail closed instead of erroring on ''::uuid.

CREATE OR REPLACE FUNCTION app.current_user_id() RETURNS uuid
  LANGUAGE sql STABLE PARALLEL SAFE
  AS $$ SELECT nullif(current_setting('app.user_id', true), '')::uuid $$;

CREATE OR REPLACE FUNCTION app.current_tenant_id() RETURNS uuid
  LANGUAGE sql STABLE PARALLEL SAFE
  AS $$ SELECT nullif(current_setting('app.tenant_id', true), '')::uuid $$;

CREATE OR REPLACE FUNCTION app.is_platform() RETURNS boolean
  LANGUAGE sql STABLE PARALLEL SAFE
  AS $$ SELECT coalesce(nullif(current_setting('app.is_platform', true), '')::boolean, false) $$;

CREATE OR REPLACE FUNCTION app.current_actor_kind() RETURNS "ActorKind"
  LANGUAGE sql STABLE PARALLEL SAFE
  AS $$ SELECT nullif(current_setting('app.actor_kind', true), '')::"ActorKind" $$;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA app FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app.current_user_id(), app.current_tenant_id(), app.is_platform(), app.current_actor_kind()
  TO ogs_app, ogs_readonly, ogs_maint;

-- ===========================================================================
-- 4. Tables, indexes, foreign keys
-- ===========================================================================

-- CreateTable
CREATE TABLE "tenant" (
    "id" UUID NOT NULL DEFAULT uuidv7(),
    "kind" "TenantKind" NOT NULL,
    "status" "TenantStatus" NOT NULL DEFAULT 'PENDING_APPROVAL',
    "name" VARCHAR(200) NOT NULL,
    "slug" VARCHAR(100) NOT NULL,
    "version" INTEGER NOT NULL DEFAULT 0,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted_at" TIMESTAMPTZ(6),

    CONSTRAINT "tenant_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "app_user" (
    "id" UUID NOT NULL DEFAULT uuidv7(),
    "email" CITEXT NOT NULL,
    "status" "UserStatus" NOT NULL DEFAULT 'PENDING_VERIFICATION',
    "version" INTEGER NOT NULL DEFAULT 0,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted_at" TIMESTAMPTZ(6),

    CONSTRAINT "app_user_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "membership" (
    "id" UUID NOT NULL DEFAULT uuidv7(),
    "tenant_id" UUID NOT NULL,
    "user_id" UUID NOT NULL,
    "status" "MembershipStatus" NOT NULL DEFAULT 'INVITED',
    "joined_at" TIMESTAMPTZ(6),
    "ended_at" TIMESTAMPTZ(6),
    "version" INTEGER NOT NULL DEFAULT 0,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
