-- ===========================================================================
-- 5. Hand-written constraints
-- ===========================================================================

-- Exactly one PLATFORM tenant may exist (review §5).
CREATE UNIQUE INDEX "tenant_single_platform_key" ON "tenant"("kind") WHERE "kind" = 'PLATFORM';

ALTER TABLE "tenant" ADD CONSTRAINT "tenant_slug_format_chk"
  CHECK ("slug" ~ '^[a-z0-9]+(-[a-z0-9]+)*$');
ALTER TABLE "tenant" ADD CONSTRAINT "tenant_version_chk" CHECK ("version" >= 0);
ALTER TABLE "app_user" ADD CONSTRAINT "app_user_version_chk" CHECK ("version" >= 0);
ALTER TABLE "membership" ADD CONSTRAINT "membership_version_chk" CHECK ("version" >= 0);
ALTER TABLE "membership" ADD CONSTRAINT "membership_ended_chk"
  CHECK (("status" = 'ENDED') = ("ended_at" IS NOT NULL));

-- Dotted lower-case event/action names, e.g. "tenant.created", "platform.context_used".
ALTER TABLE "audit_log" ADD CONSTRAINT "audit_log_action_format_chk"
  CHECK ("action" ~ '^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$');
ALTER TABLE "audit_log" ADD CONSTRAINT "audit_log_metadata_object_chk"
  CHECK (jsonb_typeof("metadata") = 'object');
ALTER TABLE "outbox_event" ADD CONSTRAINT "outbox_event_type_format_chk"
  CHECK ("type" ~ '^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$');
ALTER TABLE "outbox_event" ADD CONSTRAINT "outbox_event_attempts_chk" CHECK ("attempts" >= 0);

-- ===========================================================================
-- 6. Audit log immutability (applies to every role, including the owner)
-- ===========================================================================

CREATE OR REPLACE FUNCTION app.reject_audit_mutation() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  RAISE EXCEPTION 'audit_log is append-only (% rejected)', TG_OP
    USING ERRCODE = 'insufficient_privilege';
END
$$;
REVOKE ALL ON FUNCTION app.reject_audit_mutation() FROM PUBLIC;

CREATE TRIGGER "audit_log_reject_update_delete"
  BEFORE UPDATE OR DELETE ON "audit_log"
  FOR EACH ROW EXECUTE FUNCTION app.reject_audit_mutation();

CREATE TRIGGER "audit_log_reject_truncate"
  BEFORE TRUNCATE ON "audit_log"
  FOR EACH STATEMENT EXECUTE FUNCTION app.reject_audit_mutation();

-- ===========================================================================
-- 7. Grants
-- ===========================================================================
-- ogs_app gets explicit per-table grants only (no default privileges), so a new
-- table is unreachable by the API until a migration deliberately grants it.
-- No DELETE anywhere: tenants, users and memberships are soft-deleted / ended.

GRANT SELECT, INSERT, UPDATE ON "tenant", "app_user", "membership" TO ogs_app;
GRANT SELECT, INSERT ON "audit_log" TO ogs_app;
GRANT SELECT, INSERT, UPDATE ON "outbox_event" TO ogs_app;

GRANT SELECT ON "tenant", "app_user", "membership", "audit_log", "outbox_event" TO ogs_readonly;
GRANT SELECT, INSERT, UPDATE, DELETE ON "tenant", "app_user", "membership", "audit_log", "outbox_event" TO ogs_maint;

ALTER DEFAULT PRIVILEGES FOR ROLE ogs_owner IN SCHEMA public GRANT SELECT ON TABLES TO ogs_readonly;
ALTER DEFAULT PRIVILEGES FOR ROLE ogs_owner IN SCHEMA public GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO ogs_maint;

-- ===========================================================================
-- 8. Row-level security
-- ===========================================================================
-- RLS enforces ISOLATION (whose rows). Authorisation (which actions a member
-- may take) is the API's job (permissions arrive in Phase 3).
-- No policy for a command = that command is denied.

ALTER TABLE "tenant"       ENABLE ROW LEVEL SECURITY, FORCE ROW LEVEL SECURITY;
ALTER TABLE "app_user"     ENABLE ROW LEVEL SECURITY, FORCE ROW LEVEL SECURITY;
ALTER TABLE "membership"   ENABLE ROW LEVEL SECURITY, FORCE ROW LEVEL SECURITY;
ALTER TABLE "audit_log"    ENABLE ROW LEVEL SECURITY, FORCE ROW LEVEL SECURITY;
ALTER TABLE "outbox_event" ENABLE ROW LEVEL SECURITY, FORCE ROW LEVEL SECURITY;

-- tenant --------------------------------------------------------------------
-- Visible as the active workspace, as one of the current user's workspaces
-- (workspace switcher), or to platform staff.
CREATE POLICY "tenant_select" ON "tenant" FOR SELECT USING (
  "id" = app.current_tenant_id()
  OR app.is_platform()
  OR EXISTS (
    SELECT 1 FROM "membership" m
     WHERE m."tenant_id" = "tenant"."id"
       AND m."user_id" = app.current_user_id()
       AND m."status" <> 'ENDED'
  )
);
-- Creating tenants is a platform action in Phase 2 (self-registration: Phase 4).
CREATE POLICY "tenant_insert" ON "tenant" FOR INSERT WITH CHECK (app.is_platform());
CREATE POLICY "tenant_update" ON "tenant" FOR UPDATE
  USING ("id" = app.current_tenant_id() OR app.is_platform())
  WITH CHECK ("id" = app.current_tenant_id() OR app.is_platform());

-- app_user ------------------------------------------------------------------
CREATE POLICY "app_user_select" ON "app_user" FOR SELECT
  USING ("id" = app.current_user_id() OR app.is_platform());
-- Registration (Phase 3) will add its own narrowly scoped policy.
CREATE POLICY "app_user_insert" ON "app_user" FOR INSERT WITH CHECK (app.is_platform());
CREATE POLICY "app_user_update" ON "app_user" FOR UPDATE
  USING ("id" = app.current_user_id() OR app.is_platform())
  WITH CHECK ("id" = app.current_user_id() OR app.is_platform());

-- membership ----------------------------------------------------------------
-- Must never reference "tenant" (tenant_select references membership: no cycles).
CREATE POLICY "membership_select" ON "membership" FOR SELECT USING (
  "tenant_id" = app.current_tenant_id()
  OR "user_id" = app.current_user_id()
  OR app.is_platform()
);
CREATE POLICY "membership_insert" ON "membership" FOR INSERT
  WITH CHECK ("tenant_id" = app.current_tenant_id() OR app.is_platform());
CREATE POLICY "membership_update" ON "membership" FOR UPDATE
  USING ("tenant_id" = app.current_tenant_id() OR app.is_platform())
  WITH CHECK ("tenant_id" = app.current_tenant_id() OR app.is_platform());

-- audit_log -----------------------------------------------------------------
-- The actor columns must equal the transaction's context: callers cannot spoof
-- who did something. A context must exist (actor_kind not null) to write at all.
CREATE POLICY "audit_log_insert" ON "audit_log" FOR INSERT WITH CHECK (
  app.current_actor_kind() IS NOT NULL
  AND "actor_kind" = app.current_actor_kind()
  AND "actor_user_id" IS NOT DISTINCT FROM app.current_user_id()
  AND ("tenant_id" IS NULL OR "tenant_id" = app.current_tenant_id() OR app.is_platform())
);
CREATE POLICY "audit_log_select" ON "audit_log" FOR SELECT USING (
  "tenant_id" = app.current_tenant_id()
  OR app.is_platform()
  OR ("tenant_id" IS NULL AND "actor_user_id" = app.current_user_id())
);

-- outbox_event --------------------------------------------------------------
-- Anyone with a context may publish for their own tenant (or tenant-less);
-- only the dispatcher (actor_kind SYSTEM) may read or mark events.
-- NOTE: INSERT ... RETURNING would need SELECT rights, so publishing uses
-- createMany (no RETURNING).
CREATE POLICY "outbox_event_insert" ON "outbox_event" FOR INSERT WITH CHECK (
  app.current_actor_kind() IS NOT NULL
  AND ("tenant_id" IS NULL OR "tenant_id" = app.current_tenant_id() OR app.is_platform())
);
CREATE POLICY "outbox_event_select" ON "outbox_event" FOR SELECT
  USING (app.current_actor_kind() = 'SYSTEM');
CREATE POLICY "outbox_event_update" ON "outbox_event" FOR UPDATE
  USING (app.current_actor_kind() = 'SYSTEM')
  WITH CHECK (app.current_actor_kind() = 'SYSTEM');
